import sys

def main():
    input = sys.stdin.readline
    a, b = map(int, input().split())
    if a == 0 and b == 0:
        sys.stdout.write("NO")
    else:
        if a == b or a - b == 1 or a - b == -1:
            sys.stdout.write("YES")
        else:
            sys.stdout.write("NO")

if __name__ == "__main__":
    main()

import sys

def main():
    input = sys.stdin.readline
    a, b = map(int, input().split())
    if a == 0 and b == 0:
        sys.stdout.write("NO\n")
    else:
        if a == b or abs(a - b) == 1:
            sys.stdout.write("YES\n")
        else:
            sys.stdout.write("NO\n")

if __name__ == "__main__":
    main()

